$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$op=[Reflection.Emit.OpCodes];$span=[type]'System.Span[int]';$ctor=$span.GetConstructor([type[]]@([int[]],[int],[int]))
function Emit-View($IL,$ArrayArg,$StartArg,$LengthArg){$IL.Emit($op::Ldarg,[int16]$ArrayArg);$IL.Emit($op::Ldarg,[int16]$StartArg);$IL.Emit($op::Ldarg,[int16]$LengthArg);$IL.Emit($op::Newobj,$ctor)}
$get=[Reflection.Emit.DynamicMethod]::new('GetBitsView',[int],[type[]]@([decimal],[int[]],[int],[int]));$il=$get.GetILGenerator();$il.Emit($op::Ldarg_0);Emit-View $il 1 2 3;$il.Emit($op::Call,[decimal].GetMethod('GetBits',[type[]]@([decimal],$span)));$il.Emit($op::Ret);$getBits=$get.CreateDelegate([Func[decimal,int[],int,int,int]])
$try=[Reflection.Emit.DynamicMethod]::new('TryGetBitsView',[bool],[type[]]@([decimal],[int[]],[int],[int],[int[]]));$il=$try.GetILGenerator();$il.Emit($op::Ldarg_0);Emit-View $il 1 2 3;$il.Emit($op::Ldarg_S,[byte]4);$il.Emit($op::Ldc_I4_0);$il.Emit($op::Ldelema,[int]);$il.Emit($op::Call,[decimal].GetMethod('TryGetBits',[type[]]@([decimal],$span,[int].MakeByRefType())));$il.Emit($op::Ret);$tryBits=$try.CreateDelegate([Func[decimal,int[],int,int,int[],bool]])
$view=[Reflection.Emit.DynamicMethod]::new('Int32ViewLength',[int],[type[]]@([int[]],[int],[int]));$il=$view.GetILGenerator();$local=$il.DeclareLocal($span);Emit-View $il 0 1 2;$il.Emit($op::Stloc_0);$il.Emit($op::Ldloca_S,$local);$il.Emit($op::Call,$span.GetProperty('Length').GetMethod);$il.Emit($op::Ret);$viewLength=$view.CreateDelegate([Func[int[],int,int,int]])
$mutate=[Reflection.Emit.DynamicMethod]::new('Int32ViewMutate',[int],[type[]]@([int[]],[int],[int],[int],[int]));$il=$mutate.GetILGenerator();$local=$il.DeclareLocal($span);Emit-View $il 0 1 2;$il.Emit($op::Stloc_0);$fill=$il.DefineLabel();$done=$il.DefineLabel();$il.Emit($op::Ldarg_3);$il.Emit($op::Brtrue,$fill);$il.Emit($op::Ldloca_S,$local);$il.Emit($op::Call,$span.GetMethod('Clear'));$il.Emit($op::Br,$done);$il.MarkLabel($fill);$il.Emit($op::Ldloca_S,$local);$il.Emit($op::Ldarg_S,[byte]4);$il.Emit($op::Call,$span.GetMethod('Fill',[type[]]@([int])));$il.MarkLabel($done);$il.Emit($op::Ldarg_2);$il.Emit($op::Ret);$mutator=$mutate.CreateDelegate([Func[int[],int,int,int,int,int]])
$copyDelegates=@{};foreach($method in @('CopyTo','TryCopyTo')){$copy=[Reflection.Emit.DynamicMethod]::new($method,[bool],[type[]]@([int[]],[int],[int],[int],[int]));$il=$copy.GetILGenerator();$local=$il.DeclareLocal($span);Emit-View $il 0 1 2;$il.Emit($op::Stloc_0);$il.Emit($op::Ldloca_S,$local);Emit-View $il 0 3 4;$il.Emit($op::Call,$span.GetMethod($method,[type[]]@($span)));if($method -eq 'CopyTo'){$il.Emit($op::Ldc_I4_1)};$il.Emit($op::Ret);$copyDelegates[$method]=$copy.CreateDelegate([Func[int[],int,int,int,int,bool]])}
$rows=[Collections.Generic.List[object]]::new();$bounds=[Collections.Generic.List[object]]::new();$operations=[Collections.Generic.List[object]]::new()
for($index=0;$index -lt $plan.bits.Count;$index++){$value=[decimal]::new([int[]]$plan.bits[$index]);foreach($length in $plan.lengths){foreach($offset in $plan.offsets){if($length -lt 0 -and $offset -ne 0){continue};foreach($route in @('get','try','try-alias')){if($route -eq 'try-alias' -and $length -lt 0){continue};$destination=$null;$capacity=[Math]::Max(0,$length);if($length -ge 0){$destination=[int[]]::new($offset+$length+$plan.suffix);for($slot=0;$slot -lt $destination.Length;$slot++){$destination[$slot]=1000+$slot}};$written=[int[]]@(99);if($route -eq 'try-alias'){$written=$destination};try{if($route -eq 'get'){$actual=$getBits.Invoke($value,$destination,$offset,$capacity)}else{$actual=$tryBits.Invoke($value,$destination,$offset,$capacity,$written)};$result=[ordered]@{ok=$true;value=$actual}}catch{$result=Failure $_};$rows.Add([ordered]@{index=$index;length=$length;offset=$offset;route=$route;result=$result;written=$written[0];buffer=$destination;afterBits=[decimal]::GetBits($value)})}}}}
foreach($spec in $plan.viewBounds){$values=$null;if($spec[0] -ge 0){$values=[int[]]::new($spec[0])};try{$result=[ordered]@{ok=$true;value=$viewLength.Invoke($values,$spec[1],$spec[2])}}catch{$result=Failure $_};$bounds.Add([ordered]@{spec=$spec;result=$result})}
